mapper.select:


    inner join sys_user u on u.user_name = tunitconfig.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tunitconfig.del_flag = '0'
     and tunitconfig.material_id = #{materialId}
     and tunitconfig.min_unit_id = #{minUnitId}
     and tunitconfig.max_unit_id = #{maxUnitId}
     and tunitconfig.count = #{count}
     and tunitconfig.status = #{status}
     and tunitconfig.material_name like concat('%', #{materialName}, '%')


${params.dataScope}
